A.teach("e2-c8-standard-2-write","c8-2-core","Contrast compression, tension, and shear, and compare one shallow and one deeper response to compression.","Compression shortens, tension stretches, and shear moves neighboring parts past each other. Shallow brittle compression can generate a reverse fault; deeper, hotter rock may fold or flow while solid.",["Defines compression.", "Defines tension and shear.", "Gives a shallow brittle compression structure.", "Gives a deeper solid ductile response."],["TB8:8.2"],{"examId": "exam2", "mock": false, "topics": ["E2C8S2"], "focusedWriting": true});
