A.teach("e2-c8-standard-5-write","c8-5-core","Distinguish anticline, syncline, and monocline, and define a hinge and axial surface.","An anticline has older rocks in its core; a syncline has younger rocks in its core; a monocline forms a step-like bend. A hinge is the region of greatest curvature, and an axial surface connects hinges across successive layers.",["States anticline age relation.", "States syncline age relation and monocline shape.", "Defines hinge.", "Defines axial surface."],["TB8:8.5"],{"examId": "exam2", "mock": false, "topics": ["E2C8S5"], "focusedWriting": true});
