L.EXAM2.topics.push({"id": "E2C8S6", "ch": 8, "title": "8.6 · Metamorphic fabrics and relict features", "sections": ["8.6"], "concepts": ["c8-6-core"], "sources": ["TB8:8.6"], "media": [{"kind": "img", "src": "assets/figures/chapter8-standard/8.6-p2-Im1.png", "width": 1500, "height": 1023, "alt": "Recognize cleavage · textbook section 8.6, PDF page 2", "cap": "Exploring Geology · 8.6 · PDF page 2 · original figure"}, {"kind": "img", "src": "assets/figures/chapter8-standard/8.6-p4-Im1.png", "width": 1500, "height": 1023, "alt": "Recognize foliation · textbook section 8.6, PDF page 4", "cap": "Exploring Geology · 8.6 · PDF page 4 · original figure"}, {"kind": "img", "src": "assets/figures/chapter8-standard/8.6-p6-Im1.png", "width": 1500, "height": 1023, "alt": "Recognize lineation · textbook section 8.6, PDF page 6", "cap": "Exploring Geology · 8.6 · PDF page 6 · original figure"}, {"kind": "img", "src": "assets/figures/chapter8-standard/8.6-p8-Im1.png", "width": 875, "height": 554, "alt": "Read inherited structures · textbook section 8.6, PDF page 8", "cap": "Exploring Geology · 8.6 · PDF page 8 · original figure"}], "standardChapter8": true});
