A.teach("e2-c8-standard-9-write","c8-9-core","Compare contact metamorphism, subduction-zone metamorphism, and regional metamorphism in a continental collision.","Shallow contact metamorphism is relatively high temperature and low pressure. Cold subduction can produce high pressure at comparatively low temperature. Collision thickens and buries crust, producing broader regional metamorphism and deformation.",["Identifies intrusion-related high-T/low-P conditions.", "Identifies subduction-related high-P/low-T conditions.", "Explains collision-related burial and heating.", "Distinguishes local contact from broader regional metamorphism."],["TB8:8.9"],{"examId": "exam2", "mock": false, "topics": ["E2C8S9"], "focusedWriting": true});
