L.EXAM2.topics.push({"id": "E2C8S10", "ch": 8, "title": "8.10 · Extension and strike-slip systems", "sections": ["8.10"], "concepts": ["c8-10-core"], "sources": ["TB8:8.10"], "media": [{"kind": "img", "src": "assets/figures/chapter8-standard/8.10-p2-Im1.png", "width": 1190, "height": 571, "alt": "Rift a continent · textbook section 8.10, PDF page 2", "cap": "Exploring Geology · 8.10 · PDF page 2 · original figure"}, {"kind": "img", "src": "assets/figures/chapter8-standard/8.10-p3-Im1.png", "width": 1110, "height": 684, "alt": "Open an ocean basin · textbook section 8.10, PDF page 3", "cap": "Exploring Geology · 8.10 · PDF page 3 · original figure"}, {"kind": "img", "src": "assets/figures/chapter8-standard/8.10-p4-Im3.png", "width": 904, "height": 384, "alt": "Move horizontally on strike-slip faults · textbook section 8.10, PDF page 4", "cap": "Exploring Geology · 8.10 · PDF page 4 · original figure"}, {"kind": "img", "src": "assets/figures/chapter8-standard/8.10-p5-Im3.png", "width": 1419, "height": 526, "alt": "Bends add local complexity · textbook section 8.10, PDF page 5", "cap": "Exploring Geology · 8.10 · PDF page 5 · original figure"}], "standardChapter8": true});
