L.EXAM2.topics.push({"id": "E2C8S11", "ch": 8, "title": "8.11 · How structures form together", "sections": ["8.11"], "concepts": ["c8-11-core"], "sources": ["TB8:8.11"], "media": [{"kind": "img", "src": "assets/figures/chapter8-standard/8.11-p3-Im2.png", "width": 789, "height": 403, "alt": "Link deformation structures · textbook section 8.11, PDF page 3", "cap": "Exploring Geology · 8.11 · PDF page 3 · original figure"}, {"kind": "img", "src": "assets/figures/chapter8-standard/8.11-p5-Im3.png", "width": 980, "height": 633, "alt": "Build a fold-and-thrust belt · textbook section 8.11, PDF page 5", "cap": "Exploring Geology · 8.11 · PDF page 5 · original figure"}, {"kind": "img", "src": "assets/figures/chapter8-standard/8.11-p6-Im3.png", "width": 770, "height": 727, "alt": "Compare bedding with cleavage · textbook section 8.11, PDF page 6", "cap": "Exploring Geology · 8.11 · PDF page 6 · original figure"}, {"kind": "img", "src": "assets/figures/chapter8-standard/8.11-p4-Im2.png", "width": 1920, "height": 786, "alt": "Separate shared from later events · textbook section 8.11, PDF page 4", "cap": "Exploring Geology · 8.11 · PDF page 4 · original figure"}], "standardChapter8": true});
