A.teach("e2-c8-standard-12-write","c8-12-core","Give two independent field clues for a fault and explain why a ridge alone does not prove an anticline.","A fault may offset matching beds and contain crushed angular fault rock; striations or a scarp can supply additional evidence. Resistant tilted beds can form ridges through differential erosion, regardless of whether a fold hinge is present.",["Gives one specific fault clue.", "Gives a second independent fault clue.", "Explains differential erosion of resistant rock.", "States why topographic height alone does not identify an anticline."],["TB8:8.12"],{"examId": "exam2", "mock": false, "topics": ["E2C8S12"], "focusedWriting": true});
