L.CH8_STANDARD.lessons.push({"n": 13, "bank": [["Direction of a horizontal line on a bed", "Strike"], ["Direction and angle of steepest descent", "Dip"], ["Fault cuts an older unit", "Fault movement is younger than that unit"], ["Unfaulted deposit seals a fault", "Sealing deposit is younger than the observed movement"], ["Mineral texture viewed under a microscope", "Metamorphic evidence"]]});
A.cards("c8s13",[{"id": "g8-13-standard", "h": "8.13 · Mechanisms and evidence", "c": ["c8-13-core"], "src": ["TB8:8.13"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Observe, measure, and record</h4><ul class=\"e2-note-points\"><li>Geologists record field sketches, photographs, rock samples, strike and dip measurements, and the positions of contacts and structures. Measurements let them project features below the surface and connect separated outcrops. Record the observation before the interpretation.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Bracket fault activity</h4><ul class=\"e2-note-points\"><li>A fault is younger than a unit it cuts. An unfaulted layer or intrusion that seals the fault is younger than the movement it seals at that exposure. These relations bracket an interval; they do not prove that a fault never moved elsewhere or at another time.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Inspect minerals and overprints</h4><ul class=\"e2-note-points\"><li>Minerals may grow before, during, or after deformation. Their shapes and positions relative to cleavage and veins can help establish a sequence. Microscopic textures and mineral chemistry add evidence about metamorphic conditions.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Integrate an event sequence</h4><ul class=\"e2-note-points\"><li>Folded veins, later cleavage, and cross-cutting features can record multiple events. Distinguish an observed overprint from the proposed explanation. Missing exposures and uncertain ages can limit the sequence to relative order rather than a precise date.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Key distinctions</h4><ul class=\"e2-note-points\"><li>Direction of a horizontal line on a bed → <mark class=\"e2-study-term\">Strike</mark>.</li><li>Direction and angle of steepest descent → <mark class=\"e2-study-term\">Dip</mark>.</li><li>Fault cuts an older unit → <mark class=\"e2-study-term\">Fault movement is younger than that unit</mark>.</li><li>Unfaulted deposit seals a fault → <mark class=\"e2-study-term\">Sealing deposit is younger than the observed movement</mark>.</li><li>Mineral texture viewed under a microscope → <mark class=\"e2-study-term\">Metamorphic evidence</mark>.</li></ul></section><details><summary>Original figures for this section</summary><figure><a href=\"assets/figures/chapter8-standard/8.13-p2-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter8-standard/8.13-p2-Im1.png\" alt=\"Observe, measure, and record · textbook section 8.13, PDF page 2\"></a><figcaption>Exploring Geology · 8.13 · PDF page 2 · original figure</figcaption></figure><figure><a href=\"assets/figures/chapter8-standard/8.13-p5-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter8-standard/8.13-p5-Im1.png\" alt=\"Bracket fault activity · textbook section 8.13, PDF page 5\"></a><figcaption>Exploring Geology · 8.13 · PDF page 5 · original figure</figcaption></figure><figure><a href=\"assets/figures/chapter8-standard/8.13-p6-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter8-standard/8.13-p6-Im1.png\" alt=\"Inspect minerals and overprints · textbook section 8.13, PDF page 6\"></a><figcaption>Exploring Geology · 8.13 · PDF page 6 · original figure</figcaption></figure><figure><a href=\"assets/figures/chapter8-standard/8.13-p7-Im2.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter8-standard/8.13-p7-Im2.png\" alt=\"Integrate an event sequence · textbook section 8.13, PDF page 7\"></a><figcaption>Exploring Geology · 8.13 · PDF page 7 · original figure</figcaption></figure></details>", "examId": "exam2", "traps": ["Use the observed geometry, rock properties and source-specific conditions before deciding on a process or history."], "media": []}]);
